import{_ as e,o,c as s,a3 as a}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Asset depreciation journals (assets 1.3.0 / accounting 1.10.0) — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Asset depreciation journals (assets 1.3.0 / accounting 1.10.0) — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/asset-depreciation-journals-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Asset depreciation journals (assets 1.3.0 / accounting 1.10.0) — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/asset-depreciation-journals-production-readiness"}]]},"headers":[],"relativePath":"deployment/asset-depreciation-journals-production-readiness.md","filePath":"deployment/asset-depreciation-journals-production-readiness.md","lastUpdated":1792280519000}'),n={name:"deployment/asset-depreciation-journals-production-readiness.md"};function r(d,t,i,c,l,u){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="asset-depreciation-journals-assets-1-3-0-accounting-1-10-0-—-production-readiness" tabindex="-1">Asset depreciation journals (assets 1.3.0 / accounting 1.10.0) — Production Readiness <a class="header-anchor" href="#asset-depreciation-journals-assets-1-3-0-accounting-1-10-0-—-production-readiness" aria-label="Permalink to &quot;Asset depreciation journals (assets 1.3.0 / accounting 1.10.0) — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-18</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Pest and headed Playwright green</td></tr><tr><td><strong>Scope</strong></td><td>Straight-line monthly depreciation journals for Assets when Accounting is installed</td></tr><tr><td><strong>Catalog</strong></td><td><strong>assets 1.2.0 → 1.3.0</strong>, <strong>accounting 1.9.0 → 1.10.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/assets">Assets user guide</a> · <a href="/user-guide/accounting-overview">Accounting</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>The first depreciation post for an asset capitalizes purchase cost: debit Fixed Assets <code>1500</code>, credit Owner Equity <code>3000</code>. Each later month debits Depreciation Expense <code>6500</code> and credits Accumulated Depreciation <code>1550</code>. The last open month of useful life takes the rounding remainder. Retired, disposed, foreign-currency, and already-posted months do not post. Without Accounting, the new fields still save and no journal is written.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Migrate-only. Existing assets are not backfilled.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Capitalize once, then straight-line months through the remainder</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Duplicate month, early month, retired, and foreign currency rejected</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Missing Accounting writes no journal</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td><code>assets.depreciate</code> required</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Batch posts eligible assets and skips the rest</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Catalog bumps and optional assets → accounting dependency</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Headed one-session SPA: empty name stays on the form; salvage and early month stay in the dialog; capitalization <code>1500</code>/<code>3000</code> and depreciation <code>6500</code>/<code>1550</code> open from Journals; duplicate month stays in the dialog; list batch skips an asset with no useful life</td><td><strong>Pass</strong> (<code>npm run test:e2e:assets:depreciation:headed</code>, 1 passed)</td></tr></tbody></table><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Reviewed the posting service, permissions, catalog bumps, SPA dialog, mobile post action, and the headed session on 2026-10-18. No product defect turned up. Validation messages stay on the create form and in the depreciation dialog. The list batch reports posted and skipped counts for every asset in the workspace, so a shared demo login will include assets left by earlier runs.</p><hr><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code>. Do not <code>db:seed</code>.</li><li>Confirm <code>modules.version</code> for <code>assets</code> is <code>1.3.0</code> and <code>accounting</code> is <code>1.10.0</code>.</li><li>Deploy Frontend after production build; hard-refresh SPA. Ship the mobile build.</li><li>Smoke: create an asset with cost, useful life, and start date → <strong>Post depreciation</strong> → journal lines <code>6500</code> / <code>1550</code>, and a capitalization journal <code>1500</code> / <code>3000</code>.</li></ol>',12)])])}const h=e(n,[["render",r]]);export{g as __pageData,h as default};
